+// changedPathHint is "; did you mean MATCH" when exactly one path of the catalog of changed paths
+// (MaterialOf) is a path suffix of the refused path or has it as a path suffix, compared on whole
+// path components, and "" otherwise. A path that leaves the root or exists in the checkout (so it
+// was refused for resolving outside it) never gets a hint.
+func (r *run) changedPathHint(path string) string {
+	if filepath.IsAbs(path) {
+		return ""
+	}
+	clean := filepath.ToSlash(filepath.Clean(path))
+	if clean == ".." || strings.HasPrefix(clean, "../") {
+		return ""
+	}
+	if _, err := os.Lstat(filepath.Join(r.in.Candidate.Root, filepath.FromSlash(clean))); err == nil {
+		return ""
+	}
+	m, err := MaterialOf(r.in)
+	if err != nil {
+		return ""
+	}
+	match, found := "", 0
+	for _, f := range m.Files {
+		p, _ := f["path"].(string)
+		if p != "" && (pathSuffix(clean, p) || pathSuffix(p, clean)) {
+			match, found = p, found+1
+		}
+	}
+	if found != 1 {
+		return ""
+	}
+	return "; did you mean " + match
+}
+
+// pathSuffix reports whether suffix is path or a path suffix of it on whole path components.
+func pathSuffix(path, suffix string) bool {
+	return path == suffix || strings.HasSuffix(path, "/"+suffix)
+}
